-- +goose Up

CREATE TABLE IF NOT EXISTS learning_enrollment (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    enrollment_id            uuid         NOT NULL,
    enrollment_key           semantic_key NOT NULL,
    learner_ref              text NOT NULL,
    offering_ref             text NOT NULL,
    status                   text NOT NULL DEFAULT 'REGISTERED',
    effective_from           date         NOT NULL,
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, enrollment_id),
    CONSTRAINT learning_enrollment_key_unique UNIQUE (tenant_id, enrollment_key),
    CONSTRAINT learning_enrollment_status_check CHECK (status IN ('REGISTERED', 'WAITLISTED', 'ATTENDED', 'CANCELLED')),
    CONSTRAINT learning_enrollment_knowledge_order CHECK (known_at <= recorded_at)
);

CREATE INDEX IF NOT EXISTS learning_enrollment_recorded
    ON learning_enrollment (tenant_id, recorded_at DESC);

ALTER TABLE learning_enrollment ENABLE ROW LEVEL SECURITY;
ALTER TABLE learning_enrollment FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON learning_enrollment
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE ON learning_enrollment TO hcmnext_app;

CREATE TABLE IF NOT EXISTS learning_completion (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    completion_id            uuid         NOT NULL,
    enrollment_id            uuid         NOT NULL,
    revision_sequence        bigint       NOT NULL,
    score                    numeric(6,2) NOT NULL,
    result                   text NOT NULL,
    verification_ref         text NOT NULL,
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, completion_id),
    CONSTRAINT learning_completion_revision_positive CHECK (revision_sequence >= 1),
    CONSTRAINT learning_completion_result_check CHECK (result IN ('PASS', 'FAIL', 'INCOMPLETE', 'WAIVED')),
    CONSTRAINT learning_completion_knowledge_order CHECK (known_at <= recorded_at),
    FOREIGN KEY (tenant_id, enrollment_id) REFERENCES learning_enrollment (tenant_id, enrollment_id)
);

CREATE INDEX IF NOT EXISTS learning_completion_recorded
    ON learning_completion (tenant_id, recorded_at DESC);

CREATE OR REPLACE TRIGGER learning_completion_append_only
    BEFORE UPDATE OR DELETE ON learning_completion
    FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

REVOKE UPDATE, DELETE ON learning_completion FROM PUBLIC;

ALTER TABLE learning_completion ENABLE ROW LEVEL SECURITY;
ALTER TABLE learning_completion FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON learning_completion
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT ON learning_completion TO hcmnext_app;

